<?php $locked = $role['code'] === 'school_admin'; ?>
<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h5 mb-0"><?= e($role['name']) ?></h2><?= $role['is_system'] ? '<span class="badge text-bg-secondary">أساسي</span>' : '' ?><?= $locked ? '<span class="badge text-bg-dark">ثابت: كل الصلاحيات</span>' : '' ?>
  <a class="btn btn-outline-secondary ms-auto" href="<?= url('school/roles') ?>">رجوع</a>
  <?php if (!$role['is_system']): ?><button class="btn btn-outline-danger" data-api="<?= url('api/v1/school/roles/' . (int)$role['id']) ?>" data-method="DELETE" data-confirm="حذف الدور؟">حذف</button><?php endif; ?></div>
<form method="put" action="<?= url('api/v1/school/roles/' . (int)$role['id']) ?>" data-ajax data-reload novalidate><?= csrf_field() ?>
  <div class="card-s mb-3"><label class="form-label" for="name">اسم الدور</label><input class="form-control" id="name" name="name" value="<?= e($role['name']) ?>" <?= $role['is_system'] ? 'readonly' : 'required' ?> style="max-width:360px"></div>
  <div class="row g-3"><?php foreach ($catalog as $module => $perms): ?><div class="col-md-6 col-xl-4"><div class="card-s h-100"><div class="d-flex justify-content-between align-items-center mb-2"><h3 class="h6 mb-0"><?= e($labels[$module] ?? $module) ?></h3><?php if (!$locked): ?><button type="button" class="btn btn-sm btn-outline-secondary" data-toggle-module>الكل</button><?php endif; ?></div>
    <?php foreach ($perms as $code => $label): $has = $locked || in_array($code, $role['perms'], true); $mine = can($code); ?><div class="form-check mb-1"><input class="form-check-input" type="checkbox" name="perms[]" value="<?= e($code) ?>" id="p_<?= e($code) ?>" <?= $has ? 'checked' : '' ?> <?= $locked || (!$mine && !$has) ? 'disabled' : '' ?>><label class="form-check-label" for="p_<?= e($code) ?>"><?= e($label) ?><?= !$mine && !$locked ? ' <small class="text-muted">(لا تملكها)</small>' : '' ?></label></div><?php endforeach; ?></div></div><?php endforeach; ?></div>
  <?php if (!$locked): ?><div class="alert alert-info mt-3 mb-0">لا يمكنك منح صلاحية لا تملكها أنت. تسري التعديلات على المستخدمين فور طلبهم التالي دون إعادة دخول.</div><button class="btn btn-primary mt-3" type="submit">حفظ الصلاحيات</button><?php endif; ?></form>
